size_t newSize = ckh->lg_sz;
ckhc_t *newTab = ckh->tab;
ckhc_t *oldTab = aTab;

for (size_t i = 0; i < (static_cast<size_t>(1) << oldSize); ++i) {
    ckhc_t *oldEntry = &oldTab[i];
    if (oldEntry->key != nullptr) {
        size_t hash = ckh->hash(oldEntry->key, oldEntry->key_len);
        size_t idx = hash & ((static_cast<size_t>(1) << newSize) - 1);
        size_t step = 1;

        while (newTab[idx].key != nullptr) {
            idx = (idx + step) & ((static_cast<size_t>(1) << newSize) - 1);
            step++;
        }

        newTab[idx] = *oldEntry;
    }
}
